import{_ as t,o as l,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"答题技巧","description":"摘自 场景面试题库","frontmatter":{},"headers":[],"relativePath":"面试/场景题/20-答题技巧.md","filePath":"面试/场景题/20-答题技巧.md","lastUpdated":1793932732000}'),r={name:"面试/场景题/20-答题技巧.md"};function e(n,a,s,u,_,h){return l(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="答题技巧" tabindex="-1">答题技巧 <a class="header-anchor" href="#答题技巧" aria-label="Permalink to &quot;答题技巧&quot;">​</a></h1><blockquote><p>摘自 <a href="./../场景面试题">场景面试题库</a></p></blockquote><h3 id="_1-star-法则" tabindex="-1">1. STAR 法则 <a class="header-anchor" href="#_1-star-法则" aria-label="Permalink to &quot;1. STAR 法则&quot;">​</a></h3><ul><li><strong>S</strong>ituation：背景（项目、场景）</li><li><strong>T</strong>ask：任务（要解决的问题）</li><li><strong>A</strong>ction：做了什么（具体方案）</li><li><strong>R</strong>esult：结果（量化数据）</li></ul><h3 id="_2-引导追问" tabindex="-1">2. 引导追问 <a class="header-anchor" href="#_2-引导追问" aria-label="Permalink to &quot;2. 引导追问&quot;">​</a></h3><ul><li>答完不要停，等面试官追问</li><li>主动说&quot;这块我印象比较深的是...&quot;引导方向</li><li>如果遇到不会的：&quot;这个我没深入过，但我觉得应该...&quot;</li></ul><h3 id="_3-展示思考过程" tabindex="-1">3. 展示思考过程 <a class="header-anchor" href="#_3-展示思考过程" aria-label="Permalink to &quot;3. 展示思考过程&quot;">​</a></h3><ul><li>不要只说答案，说为什么选这个方案</li><li>列出&quot;其他方案 + 为什么不用&quot;</li><li>量化收益（性能 +30%、维护成本 -50%）</li></ul><h3 id="_4-避开雷区" tabindex="-1">4. 避开雷区 <a class="header-anchor" href="#_4-避开雷区" aria-label="Permalink to &quot;4. 避开雷区&quot;">​</a></h3><ul><li>❌ 不要贬低前公司</li><li>❌ 不要说&quot;这个我不知道&quot;</li><li>❌ 不要背答案（要讲自己的项目）</li><li>❌ 不要过度包装（被追问会露馅）</li></ul><hr><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>场景题的通用答题结构:<strong>结论先行 → 拆解问题 → 方案与取舍 → 落地细节 → 结果与反思</strong>。</li><li>时间控制:先花 30 秒澄清约束,再展开;超过 2 分钟没讲到重点就收拢。</li><li>必须有<strong>明确结论</strong>:「我建议选 A,因为 X;如果约束变了我会选 B」。</li><li>加分动作:主动讲<strong>风险与兜底</strong>、主动给<strong>数字</strong>、主动提<strong>你没做但知道该怎么做</strong>。</li><li>禁忌:只罗列方案不做决策、过度吹嘘项目、用「我们公司规定」代替自己的判断。</li><li>复盘:每场面试后记录被问倒的问题,回本站对应页面补齐,这是最有效的提升闭环。</li></ul>',13)])])}const q=t(r,[["render",e]]);export{c as __pageData,q as default};
